def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    return float(math.log1p(v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and math.isfinite(r) and r > 0:
            total += x * r * r * r
            weight += x
    if weight <= 0:
        return 0.0
    return float(4.0 * math.pi * total / (3.0 * weight * v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if x is not None and x > 0 and z is not None and math.isfinite(z):
            total += x * z
            weight += x
    if weight <= 0:
        return 0.0
    return float(total / (weight * v))

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    if n == 0:
        return 0.0
    nearest = [math.inf] * n
    for edge in s.get('neighbors', ()):
        i = edge['i']
        d = edge['distance_A']
        if d > 1e-8 and d < nearest[i]:
            nearest[i] = d
    total = 0.0
    second = 0.0
    weight = 0.0
    for i in range(n):
        w = max(0.0, sites[i].get('occupancy', 1.0) or 0.0)
        d = nearest[i]
        if math.isfinite(d) and w > 0:
            total += w * d
            second += w * d * d
            weight += w
    if weight <= 0 or total <= 0:
        return 0.0
    mean = total / weight
    return float(math.sqrt(max(0.0, second / weight - mean * mean)) / mean)

def feature(s):
