    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    nearest = [math.inf] * n
    for edge in s.get('neighbors', ()):
        i = edge['i']
        d = edge['distance_A']
        if d > 1e-8 and d < nearest[i]:
            nearest[i] = d
    coordination = [0.0] * n
    for edge in s.get('neighbors', ()):
        i = edge['i']
        d = edge['distance_A']
        if d > 1e-8 and d <= 1.25 * nearest[i]:
            coordination[i] += occ[edge['j']]
    return float(sum(occ[i] * coordination[i] for i in range(n)) / weight)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    nearest = [math.inf] * n
    for edge in s.get('neighbors', ()):
        i = edge['i']
        d = edge['distance_A']
        if d > 1e-8 and d < nearest[i]:
            nearest[i] = d
    coordination = [0.0] * n
    for edge in s.get('neighbors', ()):
        i = edge['i']
        d = edge['distance_A']
        if d > 1e-8 and d <= 1.25 * nearest[i]:
            coordination[i] += occ[edge['j']]
    mean = sum(occ[i] * coordination[i] for i in range(n)) / weight
    if mean <= 0:
        return 0.0
    variance = sum(occ[i] * (coordination[i] - mean) ** 2 for i in range(n)) / weight
    return float(math.sqrt(max(0.0, variance)) / mean)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    if n == 0:
        return 0.0
    props = s.get('element_properties', {})
    en = [props.get(t.get('element'), {}).get('eneg') for t in sites]
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    nearest = [math.inf] * n
    for edge in s.get('neighbors', ()):
        i = edge['i']
        d = edge['distance_A']
        if d > 1e-8 and d < nearest[i]:
            nearest[i] = d
    total = 0.0
    for edge in s.get('neighbors', ()):
        i = edge['i']
        j = edge['j']
        d = edge['distance_A']
        if d > 1e-8 and d <= 1.25 * nearest[i] and en[i] is not None and en[j] is not None:
            total += occ[i] * occ[j] * (en[i] - en[j]) ** 2 / d
    return float(0.5 * total / weight)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    nearest = [math.inf] * n
    for edge in s.get('neighbors', ()):
        i = edge['i']
        d = edge['distance_A']
        if d > 1e-8 and d < nearest[i]:
            nearest[i] = d
    same = 0.0
    weight = 0.0
    for edge in s.get('neighbors', ()):
        i = edge['i']
        j = edge['j']
        d = edge['distance_A']
        if d > 1e-8 and d <= 1.25 * nearest[i]:
            w = occ[i] * occ[j]
            weight += w
            if sites[i]['element'] == sites[j]['element']:
                same += w
    fractions = [x for x in s.get('composition', {}).values() if x is not None and x > 0]
    total_fraction = sum(fractions)
    if weight <= 0 or total_fraction <= 0:
        return 0.0
    baseline = sum(x * x for x in fractions) / (total_fraction * total_fraction)
    return float(same / weight - baseline)
